(* [comment removed for export] *)
Definition rb2_rows_exit (sp gp tp t0 t1 t2 s0 s1 a0 a4 a6 a7 s2 s3 s4 s5 s9 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem)
    (datas wpls datad wpld nr rsd : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' a1' a2' a3' s8' s10' t4' t5' t6' : word) (m' : mem) (dbs' : list byte),
    ms' = MS (mkR ra' sp gp tp t0 t1 t2 s0 s1 a0 a1' a2' a3' a4 (Z_to_bv 64 nr) a6 a7
                  s2 s3 s4 s5 (Z_to_bv 64 (datas + 8 * wpls * nr)) (Z_to_bv 64 (datad + 4 * wpld * nr)) s8' s9 s10' (Z_to_bv 64 SHB)
                  (Z_to_bv 64 (datas + 8 * wpls * nr)) t4' t5' t6')
             F (Z_to_bv 64 0x15eecc) fc None m' (seg_rom asegs)
    /\ munch [(datad, datad + rsd)] m m' /\ wmono asegs m m' /\ mem_inv asegs m' /\ u8arr asegs m' datad dbs' /\ Z.of_nat (length dbs') = rsd.

Lemma rb2_rows : forall (k : nat) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 t3 t4 t5 t6 : word) F fc (m : mem)
    (datas ns wpls nw tab datad rsd wpld nr : Z) (sbs : list byte) (tbs : list byte) (dbs : list byte),
  a5 = Z_to_bv 64 i -> t1 = Z_to_bv 64 nr -> s7 = Z_to_bv 64 (datad + 4 * wpld * i) ->
  s6 = Z_to_bv 64 (datas + 8 * wpls * i) -> t3 = Z_to_bv 64 (datas + 8 * wpls * i) ->
  t0 = Z_to_bv 64 nw -> a4 = Z_to_bv 64 nw -> s9 = Z_to_bv 64 (4 * wpld) -> a6 = Z_to_bv 64 (8 * wpls) -> t2 = Z_to_bv 64 (4 * wpls) ->
  a0 = Z_to_bv 64 tab -> a7 = Z_to_bv 64 0xffffffffaaaaaaaa ->
  Z.of_nat k = nr - i -> 0 <= i -> (1 <= k)%nat -> nr < 2^31 ->
  1 <= nw <= wpls -> nw <= 2 * wpld -> 0 <= wpld -> 8 * wpls * nr <= ns -> 4 * wpld * nr <= rsd ->
  0 < datas -> datas mod 8 = 0 -> datas + ns <= 2^47 -> (datas + ns <= 0x7fff7000 \/ 0x10007fff8000 <= datas) ->
  bytes_at asegs m datas sbs -> Z.of_nat (length sbs) = ns -> acc asegs m datas ns ->
  0 < tab -> tab mod 16 = 0 -> tab + 256 <= 2^47 -> (tab + 256 <= 0x7fff7000 \/ 0x10007fff8000 <= tab) ->
  bytes_at asegs m tab tbs -> Z.of_nat (length tbs) = 256 -> acc asegs m tab 256 ->
